+test "empty commands opens a shell" {
+    const testing = std.testing;
+    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
+    defer arena.deinit();
+
+    const request = try testParse(arena.allocator(), "(@aa{sv} [], b'', @a{sv} {}, @a{sv} {})");
